package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.*; import com.innovatus.studentrecords.service.SessionManager; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import java.awt.*; public class DownloadFrame extends BaseFrame {public DownloadFrame(){super("Download Filtered Records");JTextField d=new JTextField(),y=new JTextField(),b=new JTextField(),s=new JTextField();JPanel p=new JPanel(new GridLayout(0,2));for(Object[] x:new Object[][]{{"Department",d},{"Year",y},{"Batch",b},{"Semester",s}}){p.add(new JLabel((String)x[0]));p.add((Component)x[1]);}JButton go=button("Export and Email");p.add(go);add(p);go.addActionListener(e->{try{var u=SessionManager.user();var rows=new ViewController().find(u.id(),"",d.getText(),y.getText(),b.getText(),s.getText());new DownloadController().exportAndEmail(u.email(),rows);DialogUtil.info(this,"Export generated and emailed.");}catch(Exception x){DialogUtil.error(this,x.getMessage());}});}}
